from more_itertools import zip_broadcast
class Once:
    opened = False
    def __iter__(self):
        if self.opened:
            raise RuntimeError("input opened twice")
        self.opened = True
        return iter([1, 2])
assert list(zip_broadcast("label", Once())) == [("label", 1), ("label", 2)]

