from more_itertools import zip_broadcast
class Counted:
    def __init__(self, values):
        self.values, self.calls = values, 0
    def __iter__(self):
        self.calls += 1
        assert self.calls == 1, "iterator acquired repeatedly"
        return iter(self.values)
for strict in (False, True):
    for values in ([], [4], [3, 8, 9]):
        source = Counted(values)
        assert list(zip_broadcast(7, source, "x", strict=strict)) == [(7, v, "x") for v in values]
        assert source.calls == 1
assert list(zip_broadcast([1, 2], [3])) == [(1, 3)]
try:
    list(zip_broadcast([1, 2], [3], strict=True))
except ValueError:
    pass
else:
    raise AssertionError("strict length mismatch must fail")
assert list(zip_broadcast("ab", [1, 2], scalar_types=None)) == [("a", 1), ("b", 2)]
